$items=@(); $sets=@{Petrolina='Alto do Cocar|Antônio Cassimiro|Areia Branca|Atrás da Banca|Boa Esperança|Caminho do Sol|Carneiro|Centro|Cidade Universitária|Cohab Massangano|Cohab São Francisco|Colônia Imperial|Cosme e Damião|Distrito Industrial|Dom Avelar|Dona Alexandrina|Fernando Idalino|Gercino Coelho|Henrique Leite|Jardim Amazonas|Jardim Maravilha|Jardim Petrópolis|Jardim São Paulo|Jatobá|João de Deus|José e Maria|Km 2|Maria Auxiliadora|Ouro Preto|Palhinhas|Pedra do Bode|Pedra Linda|Pedro Raimundo|Portal da Cidade|Rio Claro|Rio Corrente|São Gonçalo|São José|Terra do Sul|Topázio|Vale Grande Rio|Vila Eduardo|Vila Eulália|Vila Mocó|Nova Petrolina|Parque São Gonçalo|Alto da Boa Vista|Aeroporto|Cohab 6|Jardim Guanabara|Jardim Guararapes|Jardim Imperial|Mandacaru|Nova Vida|Novo Tempo|São Rafael';Juazeiro='Alagadiço|Alto da Aliança|Alto da Maravilha|Alto do Alencar|Alto do Cruzeiro|Angary|Antônio Conselheiro|Antonio Guilhermino|Argemiro|Cajueiro|Castelo Branco|Centenário|Centro|Coréia|Country Club|Distrito Industrial|Dom José Rodrigues|Dom Tomaz|Expedito de Almeida Nascimento|Itaberaba|Jardim Flórida|Jardim Novo Encontro|Jardim Primavera|Jardim São Paulo|Jardim Universitário|Jardim Vitória|João Paulo II|João XXIII|Lomanto Júnior|Malhada da Areia|Maringá|Monte Castelo|Mussambê|Nossa Senhora da Penha|Nossa Senhora das Grotas|Nova Esperança|Nova Juazeiro|Padre Vicente|Palmares|Parque Centenário|Parque Residencial|Pedra do Lord|Pedro Raimundo|Piranga|Piranga I|Piranga II|Quidé|Santa Maria Goretti|Santo Antônio|São Geraldo|Sol Levante|Tabuleiro|Tancredo Neves|Vila Tiradentes'};foreach($city in $sets.Keys){foreach($name in $sets[$city].Split('|')){try{$u='https://photon.komoot.io/api/?limit=1&q='+[uri]::EscapeDataString("$name, $city, Brasil");$f=(Invoke-RestMethod -Uri $u -TimeoutSec 15).features[0];if($f){$items+=,[pscustomobject]@{city=$city;name=$name;lon=$f.geometry.coordinates[0];lat=$f.geometry.coordinates[1]}}}catch{}}};function Fee([double]$k){$v=@{1=600;2=700;3=800;4=900;5=1000;6=1100;7=1200;8=1300;9=1400;10=1600;11=1700;12=1800;13=1900;14=2350;15=2500;16=2650;17=2800;18=2950;19=3100;20=3250;21=3400;22=3550;23=3700;24=3850;25=4000;26=4150;27=5150;28=5300;29=5500;30=5700};if($k -le 1){return 600};return $v[[math]::Min(30,[math]::Ceiling($k))]};$sql="-- Rotas calculadas via Photon/OSRM.`nUPDATE branches SET longitude=-40.491637,latitude=-9.3566724 WHERE id='dom-avelar';`nUPDATE branches SET longitude=-40.5465894,latitude=-9.3930368 WHERE id='sao-goncalo';`n";$orig=@{'dom-avelar'='-40.491637,-9.3566724';'sao-goncalo'='-40.5465894,-9.3930368'};foreach($branch in $orig.Keys){foreach($chunk in @($items | ForEach-Object -Begin {$x=@()} -Process {$x+=$_;if($x.Count -eq 40){,$x;$x=@()}} -End {if($x.Count){,$x}})){$coords=$orig[$branch]+';'+(($chunk|ForEach-Object{"$($_.lon),$($_.lat)"}) -join ';');$dst=(1..$chunk.Count)-join ';';try{$d=(Invoke-RestMethod -Uri "https://router.project-osrm.org/table/v1/driving/$coords?sources=0&destinations=$dst" -TimeoutSec 40).distances[0];for($i=0;$i -lt $chunk.Count;$i++){if($null -ne $d[$i]){$km=[math]::Round($d[$i]/1000,1);$n=$chunk[$i].name.Replace("'","''");$sql+="INSERT OR REPLACE INTO branch_neighborhood_fees (branch_id,city,neighborhood,distance_km,fee_cents,updated_at) VALUES ('$branch','$($chunk[$i].city)','$n',$km,$(Fee $km),CURRENT_TIMESTAMP);`n"}}}catch{}}};Set-Content -Encoding utf8 drizzle/0028_calculated_neighborhood_fees.sql $sql;Write-Output "Geocodificados: $($items.Count)";
